return $input.all().map(item => {
  const url = item.json.url;

  // Спробуємо витягнути ID з двох форматів
  let match = url.match(/\/d\/([a-zA-Z0-9_-]+)/); // формат /d/ID/
  if (!match) {
    match = url.match(/[?&]id=([a-zA-Z0-9_-]+)/); // формат ?id=ID
  }

  if (!match) {
    throw new Error("Не вдалося витягнути ID файлу з URL: " + url);
  }

  return {
    json: {
      ...item.json, // зберігаємо всі попередні дані
      fileId: match[1]
    }
  };
});

