        });
    }
}

return results;

const inputData = $input.all().map(i => i.json);

// Масив технічних ключів, які треба видалити
const technicalKeysPattern = /^__EMPTY/;

const cleanedData = inputData.map(row => {
  const newRow = {};
  for (const key in row) {
    if (!technicalKeysPattern.test(key)) {
      // Зберігаємо null для порожніх клітинок
      newRow[key] = row[key] === undefined ? null : row[key];
    }
  }
  return newRow;
});

// Перетворюємо в рядок для ChatGPT
const outputString = JSON.stringify(cleanedData);

return [
  {
    json: {
      content: outputString
    }
  }
];

