  if (!name) return `unnamed_${Date.now()}`;
  return name
    .replace(/\s+/g, '_')        // заміна пробілів на підкреслення
    .replace(/[^\w\-\.]/g, '');  // видалення небезпечних символів
};

return $input.all().map(item => {
  const originalName = item.binary?.data?.fileName;
  const inputFileName = sanitizeFileName(originalName);
  const unsignedFileName = `unsigned-${inputFileName}`;
  const outputFileName = `ocr-${inputFileName}`;
  const mountDir = '/opt/n8n/shared-pdf';

  // Команда: якщо PDF вже має текст — копіюємо, інакше запускаємо OCR
  const command = `
if docker run --rm -v ${mountDir}:/data poppler-utils pdftotext /data/${unsignedFileName} - | grep -q '[A-Za-z0-9]'; then
  echo "PDF already has text, skipping OCR.";
  cp /data/${unsignedFileName} /data/${outputFileName};
else
  echo "Running OCR...";
  docker run --rm -v ${mountDir}:/data jbarlow83/ocrmypdf --skip-text --output-type pdf /data/${unsignedFileName} /data/${outputFileName} || \
  docker run --rm -v ${mountDir}:/data jbarlow83/ocrmypdf --force-ocr --output-type pdf /data/${unsignedFileName} /data/${outputFileName};
fi
  `.trim();

  return {
    json: {
      ...item.json,
      originalName,
      inputFileName,
      unsignedFileName,
      outputFileName,
      command
    }
  };
});

