// ---------- HELPERS ----------
function isEmptyVal(v) {
  return v === null || v === undefined || v === "" || (Array.isArray(v) && v.length === 0);
}

function normText(v) {
  if (v === null || v === undefined) return "";
  if (Array.isArray(v)) return v.map(x => normText(x)).join(" ");
  return String(v).replace(/\s+/g, " ").trim().toLowerCase();
}

function normNumericStr(v) {
  if (v === null || v === undefined) return "";
  let s = String(v).replace(/\s+/g, "");
  if (/^\d+,\d+$/.test(s)) s = s.replace(",", ".");
  s = s.replace(/[^0-9.\-]/g, "");
  return s;
}

function bothEmpty(a, b) {
  return isEmptyVal(a) && isEmptyVal(b);
}

function decideMatch(actualRaw, expectedRaw) {
  if (bothEmpty(actualRaw, expectedRaw)) return "full";

  // Спочатку перевіряємо масиви
  if (Array.isArray(actualRaw) && Array.isArray(expectedRaw)) {
    let foundMatches = 0;

    // Для кожного елементу в очікуваному масиві
    for (const expectedItem of expectedRaw) {
      let found = false;

      // Шукаємо в actualRaw
      for (const actualItem of actualRaw) {
        if (Array.isArray(actualItem)) {
          // Якщо actualItem - вкладений масив, шукаємо в ньому
          for (const nestedItem of actualItem) {
            if (String(nestedItem) === String(expectedItem)) {
              found = true;
              break;
            }
          }
          if (found) break;
        } else {
          // Якщо actualItem - не масив, порівнюємо напряму
          if (String(actualItem) === String(expectedItem)) {
            found = true;
          }
        }
        if (found) break;
      }

      if (found) {
        foundMatches++;
      }
    }

    // Визначаємо результат
    if (foundMatches === expectedRaw.length) {
      return "partial";
    } else if (foundMatches > 0) {
      return "partial";
    }

    return "none";
  }

  // Для не-масивів виконуємо звичайні перевірки
  const aText = normText(actualRaw);
  const eText = normText(expectedRaw);
  const aNum = normNumericStr(actualRaw);
  const eNum = normNumericStr(expectedRaw);

  if (aNum !== "" && eNum !== "") {
    if (aNum === eNum) return "full";
    if (aNum.includes(eNum) || eNum.includes(aNum)) return "partial";
    return "none";
  }

  if (aText === eText && aText !== "") return "full";
  if (aText && eText && (aText.includes(eText) || eText.includes(aText))) return "partial";

  if ((aText === "" && eText !== "") || (aText !== "" && eText === "")) return "none";

  return "none";
}

function matchBgColor(match) {
  if (match === "full") return "#ccffcc";    
  if (match === "partial") return "#fff7b3"; 
  return "#ffcccc";                          
}

function escapeHtml(s) {
  if (s === null || s === undefined) return "";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function formatValueForDisplay(value) {
  if (isEmptyVal(value)) return "";
  if (Array.isArray(value)) {
    return value.map(item => escapeHtml(item)).join("<br>");
  }
  return escapeHtml(value);
}

