function normalizePercentages(obj) {
    if (typeof obj !== 'object' || obj === null) return obj;

    const normalized = Array.isArray(obj) ? [...obj] : {...obj};

    Object.keys(normalized).forEach(key => {
        const value = normalized[key];

        if (typeof value === 'string') {
            // Нормалізація процентних значень (заміна крапки на кому)
            if (value.includes('%')) {
                normalized[key] = value.replace(/\.(?=\d+%)/g, ',');
            }
            // Нормалізація валютних значень (заміна крапки на кому)
            else if (value.includes('$') && value.match(/\d+\.\d+/)) {
                normalized[key] = value.replace(/(\d+)\.(\d+)/g, '$1,$2');
            }
        } else if (Array.isArray(value)) {
            // Нормалізуємо масиви
            normalized[key] = value.map(item => {
                if (typeof item === 'string') {
                    let normalizedItem = item;
                    // Нормалізація процентних значень
                    if (item.includes('%')) {
                        normalizedItem = normalizedItem.replace(/\.(?=\d+%)/g, ',');
                    }
                    // Нормалізація валютних значень
                    if (item.includes('$') && item.match(/\d+\.\d+/)) {
                        normalizedItem = normalizedItem.replace(/(\d+)\.(\d+)/g, '$1,$2');
                    }
                    return normalizedItem;
                }
                return item;
            });
        } else if (typeof value === 'object' && value !== null) {
            // Рекурсивно нормалізуємо вкладені об'єкти
            normalized[key] = normalizePercentages(value);
        }
    });

    return normalized;
}

