    arr2.forEach((value, index) => {
        if (index < result.length) {
            // Елемент з таким індексом вже існує
            result[index] = mergeSimpleValues(result[index], value);
        } else {
            // Новий індекс - просто додаємо
            result.push(value);
        }
    });

