}

// Функція для об'єднання простих значень
function mergeSimpleValues(value1, value2) {
    // Перевірка на порожні значення
    const isEmpty1 = value1 === '' || value1 === null || value1 === undefined;
    const isEmpty2 = value2 === '' || value2 === null || value2 === undefined;

    // Якщо обидва порожні - залишаємо пусту строку
    if (isEmpty1 && isEmpty2) return '';

    // Якщо одне порожнє - повертаємо інше
    if (isEmpty1) return value2;
    if (isEmpty2) return value1;

    // Перевірка на нулі
    const isZero1 = value1 === 0 || value1 === '0';
    const isZero2 = value2 === 0 || value2 === '0';

    // Якщо обидва нулі - залишаємо один 0 (число)
    if (isZero1 && isZero2) return 0;

    // Якщо один нуль - повертаємо інше значення
    if (isZero1) return value2;
    if (isZero2) return value1;

    // Нормалізація процентних та валютних значень (заміна крапки на кому)
    if (typeof value1 === 'string' || typeof value2 === 'string') {
        // Функція для нормалізації процентних та валютних значень
        const normalizeValue = (str) => {
            if (typeof str === 'string') {
                let normalized = str;
                // Нормалізація процентних значень
                if (str.includes('%')) {
                    normalized = normalized.replace(/\.(?=\d+%)/g, ',');
                }
                // Нормалізація валютних значень
                if (str.includes('$') && str.match(/\d+\.\d+/)) {
                    normalized = normalized.replace(/(\d+)\.(\d+)/g, '$1,$2');
                }
                return normalized;
            }
            return str;
        };

        // Нормалізуємо кожне значення окремо
        const normalized1 = typeof value1 === 'string' ? normalizeValue(value1) : value1;
        const normalized2 = typeof value2 === 'string' ? normalizeValue(value2) : value2;

        // Якщо нормалізовані значення співпадають - залишаємо нормалізоване
        if (normalized1 === normalized2) {
            return normalized1;
        }

        // Перевіряємо співпадіння без урахування регістру (для строк)
        if (typeof normalized1 === 'string' && typeof normalized2 === 'string') {
            if (normalized1.toLowerCase() === normalized2.toLowerCase()) {
                return normalized1;
            }
        }

        // Оновлюємо оригінальні значення на нормалізовані для подальшої обробки
        value1 = normalized1;
        value2 = normalized2;
    }

    // Перевірка на співпадіння з урахуванням регістру
    if (value1 === value2) return value1;

    // Перевірка на співпадіння без урахування регістру (для строк)
    if (typeof value1 === 'string' && typeof value2 === 'string') {
        if (value1.toLowerCase() === value2.toLowerCase()) {
            // Якщо строки співпадають без урахування регістру - залишаємо перше значення
            return value1;
        }
    }

    // Перетворюємо обидва значення в масиви для обробки
    const arr1 = Array.isArray(value1) ? value1 : [value1];
    const arr2 = Array.isArray(value2) ? value2 : [value2];

    // Об'єднуємо масиви та видаляємо дублікати (з урахуванням регістру)
    const mergedArray = [...arr1];

    arr2.forEach(item => {
        // Перевіряємо, чи вже є таке значення в масиві (з урахуванням регістру)
        const isDuplicate = mergedArray.some(existingItem => {
            if (typeof existingItem === 'string' && typeof item === 'string') {
                // Для строк - порівнюємо без урахування регістру
                return existingItem.toLowerCase() === item.toLowerCase();
            } else {
                // Для інших типів - точне порівняння
                return JSON.stringify(existingItem) === JSON.stringify(item);
            }
        });

        if (!isDuplicate) {
            mergedArray.push(item);
        }
    });

    // Якщо в результаті лише один елемент - повертаємо його як просте значення
    // Якщо більше - повертаємо масив
    return mergedArray.length === 1 ? mergedArray[0] : mergedArray;
}

// Отримуємо всі items після попередньої обробки
const processedItems = $input.all().map(item => {
    const output = item.json;

    if (output && output.action === "parse" && typeof output.text === "string") {
        const text = output.text.replace(/```json\s*|```/g, "").trim();
        try {
            const parsed = JSON.parse(text);
            const result = parsed.output || parsed;
            // Нормалізуємо процентні та валютні значення перед поверненням
            return normalizePercentages(result);
        } catch (err) {
